parameters.jsCode:
// Parse the Claude response to extract JSON
const response = $input.item.json;
let jsonOutput;

// Handle different response structures from Anthropic
if (response.content && Array.isArray(response.content)) {
  // New Anthropic API format
  const textContent = response.content.find(item => item.type === 'text');
  if (textContent && textContent.text) {
    jsonOutput = JSON.parse(textContent.text);
  }
} else if (response.completion) {
  // Legacy format
  jsonOutput = JSON.parse(response.completion);
} else if (typeof response === 'string') {
  // Direct string response
  jsonOutput = JSON.parse(response);
} else {
  // Assume it's already parsed
  jsonOutput = response;
}

return { json: { STAGE_1_REPORT: jsonOutput } };

