parameters.jsCode:
// Extract the content from Anthropic response
const response = $input.item.json;
let contentOutput;

// Handle different response structures
if (response.content && Array.isArray(response.content)) {
  const textContent = response.content.find(item => item.type === 'text');
  if (textContent && textContent.text) {
    contentOutput = textContent.text;
  }
} else if (response.completion) {
  contentOutput = response.completion;
} else if (typeof response === 'string') {
  contentOutput = response;
} else {
  contentOutput = JSON.stringify(response);
}

// Split content into platform sections
const sections = {
  full_content: contentOutput,
  timestamp: new Date().toISOString(),
  stage1_report: $('Parse Stage 1 JSON').item.json.STAGE_1_REPORT
};

// Try to extract individual platform sections
const linkedinMatch = contentOutput.match(/## Authority Builder: LinkedIn Post([\s\S]*?)(?=##|$)/);
const instagramMatch = contentOutput.match(/## Engagement Driver: Instagram\/Threads Post([\s\S]*?)(?=##|$)/);
const tiktokMatch = contentOutput.match(/## Conversion Closer: TikTok\/YouTube Shorts Script([\s\S]*?)(?=##|$)/);

if (linkedinMatch) sections.linkedin_content = linkedinMatch[1].trim();
if (instagramMatch) sections.instagram_content = instagramMatch[1].trim();
if (tiktokMatch) sections.tiktok_content = tiktokMatch[1].trim();

return { json: sections };
